@parity "wasm_builder/lib/src/builder/instructions.dart:258 InstructionsBuilder.collectUsedTypes" function collect_used_types(b::InstructionsBuilder, used_types::LinkedHashSet{IR.DefType})::Nothing
    for l in b.locals
        local_def_type = contained_def_type(l.type)
        local_def_type === nothing || push!(used_types, local_def_type)
    end
    for instruction in b._instructions
        for t in used_def_types(instruction)
            push!(used_types, t)
        end
        for value_type in used_value_types(instruction)
            type = contained_def_type(value_type)
            type === nothing || push!(used_types, type)
        end
    end
    for patch in b._patch_points
        collect_used_types(patch.patch_builder, used_types)
    end
    nothing
end

@parity "wasm_builder/lib/src/builder/instructions.dart:276 InstructionsBuilder.forceBuild" function force_build(b::InstructionsBuilder)::IR.Instructions
    if isempty(b._patch_points)
        return IR.Instructions(b.locals, b.local_names, b._instructions, b._stack_traces, b._trace_lines, b._source_mappings)
    end

    # Fill in the patched instructions and update the source maps.

    instructions = b._instructions
    new_instructions = IR.Instruction[]
    source_mappings = b._source_mappings
    new_source_mappings = source_mappings === nothing ? nothing : SourceMapping[]

    # The number of additional patch instructions emitted. `ini` and `smi` are 0-based, as dart's.
    shift = 0
    ini = 0
    smi = source_mappings !== nothing ? 0 : -1

    for patch in b._patch_points
        # Add every instruction before the patch starts.
        while ini < patch.start
            push!(new_instructions, instructions[ini+1])
            ini += 1
        end
        # Advance the current source mapping to the last one covering the start of the region.
        if source_mappings !== nothing && smi < length(source_mappings)
            while smi < length(source_mappings) - 1 && source_mappings[smi+2].instruction_offset <= patch.start
                push!(new_source_mappings, shift_by(source_mappings[smi+1], shift))
                smi += 1
            end
        end
        # Add the patched instructions and update the shift.
        replacement = patch.patch_builder._instructions
        append!(new_instructions, replacement)
        shift += length(replacement)
    end

    # Add the remaining instructions and shift the remaining source map entries.
    while ini < length(instructions)
        push!(new_instructions, instructions[ini+1])
        ini += 1
    end
    if source_mappings !== nothing && shift != 0
        while smi < length(source_mappings)
            push!(new_source_mappings, shift_by(source_mappings[smi+1], shift))
            smi += 1
        end
    end

    IR.Instructions(b.locals, b.local_names, new_instructions, b._stack_traces, b._trace_lines, new_source_mappings)
end

